package dev.kubejseditor.client;

import com.google.gson.*;
import dev.kubejseditor.recipe.compat.*;
import dev.kubejseditor.runtime.*;
import dev.kubejseditor.storage.ProjectStore;
import mezz.jei.api.recipe.RecipeIngredientRole;
import java.util.*;
import static dev.kubejseditor.recipe.compat.CompatDefinition.*;

/** Lazily relates typed native JSON to complete public JEI slots. No mod/type-name whitelist. */
public final class CompatAutoDiscovery {
    private final JsonObject data;private final CompatJeiLayouts.View view;private final CompatDefinition definition;
    private CompatAutoDiscovery(JsonObject data,CompatJeiLayouts.View view,RecipePresentation seed){this.data=data;this.view=view;definition=seed==null?new CompatDefinition(data.get("type").getAsString(),"jei-native"):ProjectStore.JSON.fromJson(ProjectStore.JSON.toJson(seed.definition),CompatDefinition.class);definition.modVersion=CompatibilityRecipes.modVersion(definition.type);if(seed!=null&&seed.definition.source.equals("legacy-simple"))for(var f:definition.fields)if(f.slot())CompatFields.shape(f,CompatJson.get(data,f.path));}
    public static RecipePresentation discover(JsonObject data,CompatJeiLayouts.View view,RecipePresentation seed){var auto=new CompatAutoDiscovery(data,view,seed);if(seed!=null&&!seed.definition.automatic())return new RecipePresentation(data,auto.definition);auto.walk(data,"",0);auto.groupLists();var presentation=new RecipePresentation(data,auto.definition);for(var b:presentation.bindings())if(b.field().kind==Kind.OTHER)try{var raw=presentation.nativeValue(b);CompatIngredientTypes.decode(b.field().ingredientType,b.field().valuePath.isBlank()?raw:CompatJson.get(raw,b.field().valuePath));}catch(RuntimeException error){b.field().readOnlyReason="缺少此原料的有效 JEI 编码："+b.field().ingredientType;}else if(b.field().slot()&&b.field().kind!=Kind.OTHER&&!presentation.nativeValue(b).isJsonNull())try{var item=presentation.item(b);if(!item.has("alternatives")&&List.of("item","id","fluid","tag","items","type").stream().noneMatch(item::has))b.field().readOnlyReason="此原生原料结构需要确认格式，其他字段仍可编辑";}catch(RuntimeException e){b.field().readOnlyReason="此字段尚未完整识别："+e.getMessage();}auto.definition.shape=CompatJson.mappingShape(data);auto.definition.check();return new RecipePresentation(data,auto.definition);}
    private boolean covered(String path){return definition.fields.stream().anyMatch(f->(f.kind!=Kind.JSON||f.role==Role.CONDITION||f.role==Role.RESULT)&&(path.equals(f.path)||path.startsWith(f.path+"/")));}
    private void add(Field f){definition.fields.removeIf(old->old.kind==Kind.JSON&&(old.path.equals(f.path)||f.path.startsWith(old.path+"/")));definition.fields.removeIf(old->old.path.equals(f.path));definition.fields.add(f);}
    private void walk(JsonElement value,String path,int depth){if(depth>10||definition.fields.size()>=240||covered(path))return;if(!path.isEmpty()&&!value.isJsonArray()){
            var fields=new ArrayList<Field>();for(var role:List.of(Role.INPUT,Role.OUTPUT,Role.CATALYST))for(var kind:List.of(Kind.ITEM,Kind.FLUID)){var f=new Field(path,path,kind,role);CompatFields.shape(f,value);if(role==Role.OUTPUT&&f.quantity.isBlank()&&value.isJsonObject()&&value.getAsJsonObject().has("id"))f.quantity=kind==Kind.ITEM?"count":"amount";var p=single(f);var b=p.bindings().getFirst();var signature=CompatIngredients.binding(p,b);if(signature.isEmpty())continue;var matching=view.slots().stream().filter(s->roleMatches(role,s.role())&&(kind==Kind.ITEM?s.item():s.fluid())&&CompatIngredients.identities(s.ingredients()).equals(CompatIngredients.identities(signature))).toList();if(!matching.isEmpty())fields.add(f);}
            for(var type:CompatIngredientTypes.others())try{CompatIngredientTypes.decode(type.getUid(),value);var f=new Field(path,path,Kind.OTHER,Role.PARAMETER);f.ingredientType=type.getUid();String signature=CompatIngredientTypes.signature(CompatIngredientTypes.decode(type.getUid(),value));var roles=view.slots().stream().filter(s->s.ingredients().contains(signature)).map(s->role(s.role())).distinct().toList();if(roles.size()==1){f.role=roles.getFirst();fields.add(f);}}catch(RuntimeException ignored){}
            var unique=fields.stream().filter(f->f.role!=Role.CATALYST||fields.stream().noneMatch(other->other.kind==f.kind&&other.role==Role.INPUT)).toList();if(unique.size()==1){add(unique.getFirst());return;}if(!unique.isEmpty()){var f=unique.getFirst();f.role=Role.PARAMETER;f.readOnlyReason="字段对应多个槽位角色，请在初级模式确认用途";add(f);return;}
            if(value.isJsonPrimitive()){var primitive=value.getAsJsonPrimitive();if(primitive.isNumber()||primitive.isBoolean()){add(new Field(path,path,primitive.isBoolean()?Kind.BOOLEAN:Kind.NUMBER,primitive.isBoolean()?Role.CONDITION:Role.PARAMETER));return;}}
        }
        if(value.isJsonObject()){for(var entry:value.getAsJsonObject().entrySet())if(!Set.of("type","components","neoforge:conditions").contains(entry.getKey()))walk(entry.getValue(),path+"/"+CompatJson.escape(entry.getKey()),depth+1);}
        else if(value.isJsonArray()){for(int i=0;i<value.getAsJsonArray().size();i++)walk(value.getAsJsonArray().get(i),path+"/"+i,depth+1);}
    }
    private RecipePresentation single(Field f){var d=new CompatDefinition(definition.type,"probe");d.fields.add(f);return new RecipePresentation(data,d);}
    private void groupLists(){var parents=new LinkedHashSet<String>();for(var f:definition.fields)if(f.path.matches(".*/[0-9]+$"))parents.add(f.path.substring(0,f.path.lastIndexOf('/')));for(String parent:parents){var raw=CompatJson.get(data,parent);if(!raw.isJsonArray()||raw.getAsJsonArray().isEmpty())continue;var grouped=definition.fields.stream().filter(f->f.path.startsWith(parent+"/")&&f.path.substring(parent.length()+1).matches("[0-9]+")&&f.slot()).toList();if(grouped.size()!=raw.getAsJsonArray().size())continue;var first=grouped.getFirst();if(grouped.stream().anyMatch(f->!CompatFields.sameSlotSemantics(first,f)))continue;var combined=ProjectStore.JSON.fromJson(ProjectStore.JSON.toJson(first),Field.class);combined.path=parent;combined.label=parent;combined.list=true;combined.template=raw.getAsJsonArray().get(0).deepCopy();definition.fields.removeAll(grouped);add(combined);}}
    private static boolean roleMatches(Role role,RecipeIngredientRole slot){return role==Role.OUTPUT?slot==RecipeIngredientRole.OUTPUT:role==Role.CATALYST?slot==RecipeIngredientRole.CATALYST:slot==RecipeIngredientRole.INPUT;}
    private static Role role(RecipeIngredientRole role){return role==RecipeIngredientRole.OUTPUT?Role.OUTPUT:role==RecipeIngredientRole.CATALYST?Role.CATALYST:Role.INPUT;}
}
